		Cache: cacheConfig{
			Memory: memoryCacheConfig{
				Enabled: false,
				Items:   500,
			},
		},

		Server: serverConfig{
			Host:     "0.0.0.0",
			HTTPPort: 8080,
			GRPCPort: 9000,
